@serialized
def index(self, *, progress: Callable[[str], None] | None = None) -> IndexReport:
    """Fully reconcile captured bytes and publish atomically, reusing unchanged parse facts."""
    return self._index(True, progress)

def _index(self, full: bool, progress: Callable[[str], None] | None = None) -> IndexReport:
    self._tracking.dirty.clear()
    if full:
        self._cache.clear()
    try:
        report = _index.index(self.root, self.store, self._cache, progress)
    except Exception:
        self._tracking.dirty.set()
        raise
    self._active = True
    self._tracking.error = None
    if full:
        self._tracking.last_full = time.monotonic()
    return report

@serialized
def _update(self, full: bool) -> None:
    if self._store is not None and self._active:
        self._index(full)

def _view(self) -> View:
    # Preserve explicit not-indexed, incompatible and corrupt-store failures on first read.
    self.store.view()
    full = not self._active or time.monotonic() - self._tracking.last_full >= RECONCILE_SECONDS
    if full or self._tracking.dirty.is_set() or self._tracking.failed:
        self._index(full or self._tracking.failed)
    return self.store.view()

def _read[T](
    repository: str,
    data_dir: str | None,
    read: Callable[[Repository], T],
    handles: dict[str, Repository],
) -> T:
    """Retain one handle per root until shutdown; evict failed handles for explicit repair."""
    with _lock:
        anyio.from_thread.check_cancelled()
        key = os.path.realpath(repository)
        try:
            try:
                if key not in handles:
                    handles[key] = open_repository(key, data_dir=data_dir, create=False)
                return read(handles[key])
            except BaseException:
                if repo := handles.pop(key, None):
                    repo.close()
                raise
        except OxideError as error:
            log.warning("%s: %s", error.code, error)
            advice = str(error) if error.code == "invalid_argument" else _ADVICE.get(error.code)
            raise ToolError(f"error[{error.code}]: {advice or 'request failed'}") from None

handles: dict[str, Repository] = {}

def close_handles() -> None:
    with _lock:
        for repo in handles.values():
            repo.close()
        handles.clear()

@asynccontextmanager
async def lifespan(app: FastMCP) -> AsyncIterator[None]:
    try:
        yield
    finally:
        await anyio.to_thread.run_sync(close_handles)

